import java.lang.*;
import java.util.*;
import java.io.*;

public class Cutting{

    public static int[]strToIntArr(String s){
        String[] sArr = s.split(" ");
        int len = sArr.length;
        int[] retArr = new int[len];
        for(int i=0;i<len;i++){
            retArr[i] = Integer.parseInt(sArr[i]);
        }
        return retArr;
    }

    boolean checkSub(int[]aArr,int splitInd){
        int nEven = 0;
        int nOdd = 0;
        for(int i=0;i<=splitInd;i++){
            if((aArr[i]%2)==0) nEven++;
            else nOdd++;
        }
        return nEven==nOdd;
    }

    int getMaxCuts(int n, int b, int[]aArr){
        TreeMap<Integer, Deque<Integer>> byCost = new TreeMap<Integer, Deque<Integer>>();
        for(int i=1;i<aArr.length-1;i++){
            if(checkSub(aArr,i)){
                int cost = Math.abs(aArr[i]-aArr[i+1]);
                Deque<Integer> q = byCost.get(cost);
                if(q==null){
                    q = new ArrayDeque<Integer>();
                    byCost.put(cost,q);
                }
                q.add(i);
            }
        }
        int nCoins = b;
        int nCuts = 0;
        while(nCoins>0 && !byCost.isEmpty()){
            Map.Entry<Integer, Deque<Integer>> first = byCost.firstEntry();
            int cost = first.getKey();
            if(cost >= (nCoins + 1)) break;
            first.getValue().removeFirst();
            if(first.getValue().isEmpty()){
                byCost.pollFirstEntry();
            }
            nCoins -= cost;
            nCuts++;
        }
        return nCuts;
    }

    public static void main(String[]args) throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        String nbLn = br.readLine();
        String aLn =  br.readLine();
        int[]nbArr = strToIntArr(nbLn);
        int[]aArr = strToIntArr(aLn);
        Cutting cut = new Cutting();
        int n = nbArr[0];
        int b = nbArr[1];
        int maxC = cut.getMaxCuts(n,b,aArr);
        bw.write(Integer.toString(maxC));
        bw.newLine();
        bw.flush();
    }

}
